import { useState, useEffect } from 'react';
import { useData } from '../contexts/DataContext';
import { Tabs, TabsContent, TabsList, TabsTrigger } from './ui/tabs';
import ClassScheduleTab from './tabs/ClassScheduleTab';
import ClubsTab from './tabs/ClubsTab';
import PsychologistTab from './tabs/PsychologistTab';
import MenuTab from './tabs/MenuTab';
import RulesTab from './tabs/RulesTab';
import EventsTab from './tabs/EventsTab';
import AutoCarousel from './AutoCarousel';
import { Moon, Sun } from 'lucide-react';
import { Button } from './ui/button';

export default function MainDisplay() {
  const { data } = useData();
  const [activeTab, setActiveTab] = useState('schedule');
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [showCarousel, setShowCarousel] = useState(true);

  useEffect(() => {
    const tabs = ['schedule', 'clubs', 'psychologist', 'menu', 'rules', 'events'];
    let currentIndex = 0;

    const interval = setInterval(() => {
      currentIndex = (currentIndex + 1) % tabs.length;
      setActiveTab(tabs[currentIndex]);
    }, 30000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const carouselInterval = setInterval(() => {
      setShowCarousel(prev => !prev);
    }, 30000); 

    return () => clearInterval(carouselInterval);
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  return (
    <div className={`min-h-screen ${theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-gradient-to-br from-blue-50 to-purple-50'} transition-colors duration-500`}>
      {}
      <header className="sticky top-0 z-50 backdrop-blur-lg bg-white/80 dark:bg-gray-900/80 border-b border-gray-200 dark:border-gray-800 shadow-lg">
        <div className="container mx-auto px-4 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              
              <div>
             <img 
  src="data:image/jpeg;base64," 
  style={{ width: "230px", height: "80px" }} 
/>
              
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right">
                <div className="text-2xl">
                  {new Date().toLocaleDateString('mn-MN', { 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </div>
                <div className="text-gray-600 dark:text-gray-400">
                  {new Date().toLocaleTimeString('mn-MN', { 
                    hour: '2-digit', 
                    minute: '2-digit' 
                  })}
                </div>
              </div>
              <Button
                variant="outline"
                size="icon"
                onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
                className="rounded-full"
              >
                {theme === 'light' ? <Moon className="h-5 w-5" /> : <Sun className="h-5 w-5" />}
              </Button>
            </div>
          </div>
        </div>
      </header>

      {/* Carousel Section */}
      {showCarousel && (
        <div className="container mx-auto px-4 py-8">
          <AutoCarousel />
        </div>
      )}

      {/* Main Content */}
      <main className="container mx-auto px-4 py-8">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-6 h-auto bg-white dark:bg-gray-800 shadow-lg rounded-2xl p-2">
            <TabsTrigger 
              value="schedule" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-blue-600 data-[state=active]:to-blue-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg"> Хичээлийн хуваарь</span>
            </TabsTrigger>
            <TabsTrigger 
              value="clubs" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-purple-600 data-[state=active]:to-purple-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg"> Дугуйлан</span>
            </TabsTrigger>
            <TabsTrigger 
              value="psychologist" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-green-600 data-[state=active]:to-green-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg"> Сэтгэлзүйч</span>
            </TabsTrigger>
            <TabsTrigger 
  
              value="menu" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-orange-600 data-[state=active]:to-orange-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg">Хоолны меню</span>
            </TabsTrigger>
            <TabsTrigger 
              value="rules" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-red-600 data-[state=active]:to-red-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg"> Дүрэм</span>
            </TabsTrigger>
            <TabsTrigger 
              value="events" 
              className="data-[state=active]:bg-gradient-to-r data-[state=active]:from-pink-600 data-[state=active]:to-pink-500 data-[state=active]:text-white rounded-xl py-4"
            >
              <span className="text-lg"> Эвент</span>
            </TabsTrigger>
          </TabsList>

          <div className="mt-8">
            <TabsContent value="schedule" className="animate-fade-in">
              <ClassScheduleTab schedules={data.classSchedules} />
            </TabsContent>
            
            <TabsContent value="clubs" className="animate-fade-in">
              <ClubsTab clubs={data.clubs} />
            </TabsContent>
            
            <TabsContent value="psychologist" className="animate-fade-in">
              <PsychologistTab hours={data.psychologistHours} />
            </TabsContent>
            
            <TabsContent value="menu" className="animate-fade-in">
              <MenuTab menu={data.menu} />
            </TabsContent>
            
            <TabsContent value="rules" className="animate-fade-in">
              <RulesTab rules={data.rules} />
            </TabsContent>
            
            <TabsContent value="events" className="animate-fade-in">
              <EventsTab events={data.events} />
            </TabsContent>
          </div>
        </Tabs>
      </main>

      {/* Footer */}
      <footer className="mt-16 py-6 border-t border-gray-200 dark:border-gray-800">
        <div className="container mx-auto px-4 text-center text-gray-600 dark:text-gray-400">
          <p>© 2018 Индра Кибер Сургууль.</p>
        </div>
      </footer>
    </div>
  );
}
